/*
 * A293008  Primes of the form 2^q * 3^r * 7^s + 1.
 * https://oeis.org/A293008
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = the n‑th prime of the form 2^q * 3^r * 7^s + 1, counting
 *            from n = 1. The sequence is generated by construction of all
 *            “humble” numbers 2^q 3^r 7^s in increasing order and testing the
 *            successor of each number for primality
 * Range:     u8 n <= 18, u16 n <= 54, u32 n <= 54, u64 n <= 54, u128 n <= 54,
 *            big any n
 * Helpers:   grow_seq, is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdbool.h>
#include "../utils/grow_seq.h"
#include "../utils/is_prime_big.h"

seq_t a(idx_t n)
{
    /* --------------------------------------------------------------------
       Static state: lists of humble numbers and the primes found so far.
       -------------------------------------------------------------------- */
    static seq_t *humble = NULL;      /* humble numbers 2^q 3^r 7^s   */
    static size_t  hlen   = 0;        /* number of entries stored     */
    static size_t  hcap   = 0;        /* current capacity             */
    static size_t  i2 = 0, i3 = 0, i7 = 0;   /* indices used for generation */

    static seq_t *primes = NULL;      /* primes of the required form  */
    static size_t  plen   = 0;        /* number of primes found       */
    static size_t  pcap   = 0;        /* current capacity             */

    /* --------------------------------------------------------------------
       Ensure the static arrays are initialised.
       -------------------------------------------------------------------- */
    if (!humble) {
        grow_seq(&humble, &hcap, 16);   /* initial capacity for speed  */
        humble[0] = (seq_t)1;           /* 2^0 3^0 7^0 = 1             */
        hlen = 1;
    }

    if (!primes) {
        grow_seq(&primes, &pcap, 16);   /* initial capacity              */
        plen = 0;
    }

    /* --------------------------------------------------------------------
       Seed the first prime candidate 2 = 1 + 1.
       -------------------------------------------------------------------- */
    if (plen == 0) {
        seq_t cand = humble[0] + (seq_t)1; /* 2 */
        if (is_prime_big(cand)) {
            if (plen == pcap)
                grow_seq(&primes, &pcap, pcap + 16);
            primes[plen++] = cand;
            if (n == 1) return primes[0];
        }
    }

    /* --------------------------------------------------------------------
       Generate humble numbers until enough primes have been found.
       -------------------------------------------------------------------- */
    while (plen < n) {
        /* compute candidates from current indices */
        seq_t v2 = humble[i2] * (seq_t)2;
        seq_t v3 = humble[i3] * (seq_t)3;
        seq_t v7 = humble[i7] * (seq_t)7;

        /* choose the smallest */
        seq_t next = v2;
        if (v3 < next) next = v3;
        if (v7 < next) next = v7;

        /* advance indices that produced the chosen minimum */
        if (v2 == next) ++i2;
        if (v3 == next) ++i3;
        if (v7 == next) ++i7;

        /* store the new humble number */
        if (hlen == hcap)
            grow_seq(&humble, &hcap, hcap + 16);
        humble[hlen++] = next;

        /* test the successor for primality */
        seq_t cand = next + (seq_t)1;
        if (is_prime_big(cand)) {
            if (plen == pcap)
                grow_seq(&primes, &pcap, pcap + 16);
            primes[plen++] = cand;
        }
    }

    /* --------------------------------------------------------------------
       Return the requested prime.
       -------------------------------------------------------------------- */
    return primes[n - 1];
}
